// cusparseSpMV and its _bufferSize against an RTX 3060's cuSPARSE 13.0: the workspace size for each format, algorithm,
// operation, value and index type, and the lines the library prints on stderr when it refuses an argument.
//
//   - The size depends on nnz alone (measured from 1 to 4.2 million entries). The simulator gave every format and
//     algorithm the single-precision CSR size: CSR_ALG2 asks 515 bytes and up for A itself (CSC's A^T), COO 524 and up
//     for A itself and nothing for A^T, and the double and complex sizes step at other entry counts (2048, 512, 384,
//     1280 entries). nvidia/src/cusparse_api.cpp (spmv_buffer_bytes) has the formulas. Half and bfloat16 are checked
//     only where they fit them (CSR_ALG2, COO_ALG2); their other sizes are not imitated.
//   - Each refused argument prints " ** On entry to cusparseSpMV() parameter number N (name) had an illegal value: ...",
//     or " ** On entry to cusparseSpMV(): dimension mismatch, ...", with a blank line after it; the simulator printed
//     nothing. cusparseSpMV_bufferSize refuses a null alpha or beta, an unknown operation, an algorithm of another
//     format and x or y of the wrong size, which it took, and an unknown compute type is INVALID_VALUE, not
//     NOT_SUPPORTED. With COO and A^T, cusparseSpMV takes a null buffer.
// Not checked: x or y of another real type than A (the card refuses most, the simulator takes them).
#include <cuda_runtime.h>
#include <cusparse.h>
#include <unistd.h>

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <string>

static int fails = 0;

// Runs f with stderr going to a pipe and returns what it printed.
template <class F>
static std::string printed(F f, int* status) {
  std::fflush(stderr);
  int p[2];
  if (pipe(p) != 0) return "<pipe failed>";
  const int saved = dup(2);
  dup2(p[1], 2);
  *status = static_cast<int>(f());
  std::fflush(stderr);
  dup2(saved, 2);
  close(saved);
  close(p[1]);
  std::string out;
  char buf[4096];
  for (ssize_t n; (n = read(p[0], buf, sizeof buf)) > 0;) out.append(buf, static_cast<size_t>(n));
  close(p[0]);
  return out;
}
#define CASE(label, want_status, want_text, call) do { int st_ = -1; \
  const std::string got_ = printed([&] { return (call); }, &st_); \
  if (st_ != (want_status) || got_ != (want_text)) { ++fails; \
    std::printf("FAIL %s: status %d, expected %d; printed \"%s\", expected \"%s\"\n", label, st_, (want_status), \
                got_.c_str(), want_text); } } while (0)

