int main() {
  // The simulator's lines are what this checks; on the card the variable changes nothing.
  setenv("VGPU_QUIET", "0", 1);
  cusparseHandle_t h;
  if (cusparseCreate(&h) != CUSPARSE_STATUS_SUCCESS) { std::printf("FAIL cusparseCreate\n"); return 1; }
  const long long kMax = 2097153;
  void *rp = nullptr, *ci = nullptr, *v = nullptr, *x = nullptr, *y = nullptr, *buf = nullptr;
  cudaMalloc(&rp, (kMax + 1) * 8);
  cudaMalloc(&ci, kMax * 8);
  cudaMalloc(&v, kMax * 16);
  cudaMalloc(&x, kMax * 16);
  cudaMalloc(&y, kMax * 16);
  cudaMalloc(&buf, 1 << 20);
  cudaMemset(rp, 0, (kMax + 1) * 8);   // (the sizes do not read A; a zero offset array is a valid one)
  const double one[2] = {1, 0}, zero[2] = {0, 0};
  for (const Size& c : kSizes) {
    const long long n = c.nnz < 4096 ? 4096 : c.nnz;   // a square matrix with room for the entries
    const auto ix = c.i64 ? CUSPARSE_INDEX_64I : CUSPARSE_INDEX_32I;
    const auto t = static_cast<cudaDataType>(c.type);
    const cudaDataType ct = t == CUDA_R_16F || t == CUDA_R_16BF ? CUDA_R_32F : t;
    cusparseSpMatDescr_t A = nullptr;
    cusparseStatus_t made;
    if (c.fmt == 0) made = cusparseCreateCsr(&A, n, n, c.nnz, rp, ci, v, ix, ix, CUSPARSE_INDEX_BASE_ZERO, t);
    else if (c.fmt == 1) made = cusparseCreateCoo(&A, n, n, c.nnz, rp, ci, v, ix, CUSPARSE_INDEX_BASE_ZERO, t);
    else made = cusparseCreateCsc(&A, n, n, c.nnz, rp, ci, v, ix, ix, CUSPARSE_INDEX_BASE_ZERO, t);
    cusparseDnVecDescr_t X = nullptr, Y = nullptr;
    cusparseCreateDnVec(&X, n, x, t);
    cusparseCreateDnVec(&Y, n, y, t);
    size_t bytes = 0;
    int st = -1;
    // (a refusal prints its line; it is not what this part checks)
    printed([&] { return cusparseSpMV_bufferSize(h, static_cast<cusparseOperation_t>(c.op), one, A, X, zero, Y, ct,
                                                 static_cast<cusparseSpMVAlg_t>(c.alg), &bytes); }, &st);
    if (made != CUSPARSE_STATUS_SUCCESS || st != c.status || (st == 0 && static_cast<long long>(bytes) != c.bytes)) {
      ++fails;
      std::printf("FAIL size format %d alg %d %s-bit type %d op %d nnz %lld: status %d, %zu bytes; expected %d, %lld\n",
                  c.fmt, c.alg, c.i64 ? "64" : "32", c.type, c.op, c.nnz, st, bytes, c.status, c.bytes);
    }
    cusparseDestroyDnVec(X);
    cusparseDestroyDnVec(Y);
    cusparseDestroySpMat(A);
  }

  // The refusals and their lines, on a 4 x 4 single CSR (and COO) matrix with one entry per row.
  int ro[5] = {0, 1, 2, 3, 4}, cc[4] = {0, 1, 2, 3};
  cudaMemcpy(rp, ro, sizeof ro, cudaMemcpyHostToDevice);
  cudaMemcpy(ci, cc, sizeof cc, cudaMemcpyHostToDevice);
  cudaMemset(v, 0, 64);
  cusparseSpMatDescr_t A, C, R;
  cusparseCreateCsr(&A, 4, 4, 4, rp, ci, v, CUSPARSE_INDEX_32I, CUSPARSE_INDEX_32I, CUSPARSE_INDEX_BASE_ZERO, CUDA_R_32F);
  cusparseCreateCoo(&C, 4, 4, 4, rp, ci, v, CUSPARSE_INDEX_32I, CUSPARSE_INDEX_BASE_ZERO, CUDA_R_32F);
  cusparseCreateCsr(&R, 4, 6, 4, rp, ci, v, CUSPARSE_INDEX_32I, CUSPARSE_INDEX_32I, CUSPARSE_INDEX_BASE_ZERO, CUDA_R_32F);
  cusparseDnVecDescr_t X, Y, X5, Xd, V4, V6, V5, Vc;
  cusparseCreateDnVec(&X, 4, x, CUDA_R_32F);
  cusparseCreateDnVec(&Y, 4, y, CUDA_R_32F);
  cusparseCreateDnVec(&X5, 5, x, CUDA_R_32F);
  cusparseCreateDnVec(&Xd, 4, x, CUDA_R_64F);
  cusparseCreateDnVec(&V4, 4, x, CUDA_R_32F);
  cusparseCreateDnVec(&V6, 6, y, CUDA_R_32F);
  cusparseCreateDnVec(&V5, 5, y, CUDA_R_32F);
  cusparseCreateDnVec(&Vc, 4, y, CUDA_C_32F);
  float al = 1, be = 0;
  size_t sz = 0;
  const auto N = CUSPARSE_OPERATION_NON_TRANSPOSE;
  const auto T = CUSPARSE_OPERATION_TRANSPOSE;
  const auto D = CUSPARSE_SPMV_ALG_DEFAULT;
  CASE("bs null handle", 3, " ** On entry to cusparseSpMV_bufferSize() parameter number 1 (handle) had an illegal value: NULL pointer\n\n", cusparseSpMV_bufferSize(nullptr,N,&al,A,X,&be,Y,CUDA_R_32F,D,&sz));
  CASE("bs null alpha", 3, " ** On entry to cusparseSpMV_bufferSize() parameter number 3 (alpha) had an illegal value: NULL pointer\n\n", cusparseSpMV_bufferSize(h,N,nullptr,A,X,&be,Y,CUDA_R_32F,D,&sz));
  CASE("bs null A", 3, " ** On entry to cusparseSpMV_bufferSize() parameter number 4 (matA) had an illegal value: NULL pointer\n\n", cusparseSpMV_bufferSize(h,N,&al,nullptr,X,&be,Y,CUDA_R_32F,D,&sz));
  CASE("bs null X", 3, " ** On entry to cusparseSpMV_bufferSize() parameter number 5 (vecX) had an illegal value: NULL pointer\n\n", cusparseSpMV_bufferSize(h,N,&al,A,nullptr,&be,Y,CUDA_R_32F,D,&sz));
  CASE("bs null beta", 3, " ** On entry to cusparseSpMV_bufferSize() parameter number 6 (beta) had an illegal value: NULL pointer\n\n", cusparseSpMV_bufferSize(h,N,&al,A,X,nullptr,Y,CUDA_R_32F,D,&sz));
  CASE("bs null Y", 3, " ** On entry to cusparseSpMV_bufferSize() parameter number 7 (vecY) had an illegal value: NULL pointer\n\n", cusparseSpMV_bufferSize(h,N,&al,A,X,&be,nullptr,CUDA_R_32F,D,&sz));
  CASE("bs null size", 3, " ** On entry to cusparseSpMV_bufferSize() parameter number 10 (bufferSize) had an illegal value: NULL pointer\n\n", cusparseSpMV_bufferSize(h,N,&al,A,X,&be,Y,CUDA_R_32F,D,nullptr));
  CASE("bs op 99", 3, " ** On entry to cusparseSpMV_bufferSize() parameter number 2 (opA) had an illegal value: (cusparseOperation_t) 99\n\n", cusparseSpMV_bufferSize(h,(cusparseOperation_t)99,&al,A,X,&be,Y,CUDA_R_32F,D,&sz));
  CASE("bs op C real", 3, " ** On entry to cusparseSpMV_bufferSize(): type of matA (CUDA_R_32F), vecX (CUDA_R_32F), vecY (CUDA_R_32F), compute (CUDA_R_32F) is not valid when opA is CUSPARSE_OPERATION_CONJUGATE_TRANSPOSE\n\n", cusparseSpMV_bufferSize(h,CUSPARSE_OPERATION_CONJUGATE_TRANSPOSE,&al,A,X,&be,Y,CUDA_R_32F,D,&sz));
  CASE("bs alg 99", 3, " ** On entry to cusparseSpMV_bufferSize() parameter number 9 (alg) had an illegal value: (cusparseSpMVAlg_t) 99\n\n", cusparseSpMV_bufferSize(h,N,&al,A,X,&be,Y,CUDA_R_32F,(cusparseSpMVAlg_t)99,&sz));
